def can_reach_zero(arr, start):
 stack=[start];seen=set()
 while stack:
  index=stack.pop()
  if index in seen:continue
  if arr[index]==0:return True
  seen.add(index)
  for nxt in (index-arr[index],index+arr[index]):
   if 0<=nxt<len(arr):stack.append(nxt)
 return False

